void dijkstra(int V, int g[V][V], int src, int dist[]) {
  int done[V];
  for (int i = 0; i < V; i++) { dist[i] = INT_MAX; done[i] = 0; }
  dist[src] = 0;
  for (int c = 0; c < V; c++) {
    int u = -1;
    for (int v = 0; v < V; v++)
      if (!done[v] && (u == -1 || dist[v] < dist[u])) u = v;
    if (dist[u] == INT_MAX) break;      // rest unreachable
    done[u] = 1;
    for (int v = 0; v < V; v++)
      if (g[u][v] && !done[v] && dist[u] + g[u][v] < dist[v])
        dist[v] = dist[u] + g[u][v];
  }
}

